package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import com.microsoft.playwright.options.FilePayload;
import java.nio.file.Path;

final class SecurityIncidentsBrowserAcceptance {
 static void run(BrowserTest h)throws Exception{
  String group;try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(String name:new String[]{"SecBrowserAnalyst","SecBrowserPeer"})Service.createAccount(db,map("name",name,"role","agent","password",WorkflowSupport.PASSWORD));group=Service.create(db,"sys_user_group",map("short_description","Browser security response team"),"admin").get("sys_id").toString();for(String name:new String[]{"SecBrowserAnalyst","SecBrowserPeer"})db.update("INSERT INTO os_group_member(group_id,user_id) VALUES(?,?)",group,RecordAccess.owner(db,name));Service.create(db,"cmdb_ci",map("short_description","Security browser affected device"),"admin");db.connection.commit();}
  try(var playwright=Playwright.create();var browser=playwright.chromium().launch();var ac=browser.newContext();var pc=browser.newContext();var dc=browser.newContext()){
   var admin=dc.newPage();h.login(admin,"admin");admin.navigate(h.base()+"/security");admin.getByLabel("Security access for Browser security response team",new Page.GetByLabelOptions().setExact(true)).selectOption("true");admin.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save security team Browser security response team").setExact(true)).press("Enter");assertThat(admin.locator("main")).containsText("Infrastructure administrators retain access.");ReleaseBrowserAcceptance.accessible(admin);
   var analyst=ac.newPage();h.login(analyst,"SecBrowserAnalyst");analyst.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Security operations").setExact(true)).press("Enter");analyst.getByLabel("Security response team",new Page.GetByLabelOptions().setExact(true)).selectOption(group);analyst.getByLabel("Incident summary",new Page.GetByLabelOptions().setExact(true)).fill("Suspicious device activity <script>");analyst.getByLabel("Reported details").fill("Restricted investigation of suspicious device behavior");analyst.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Create security incident").setExact(true)).press("Enter");String id=analyst.url().split("/")[5];analyst.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Security incident workspace").setExact(true)).press("Enter");assertThat(analyst.getByLabel("Security incident summary",new Page.GetByLabelOptions().setExact(true))).hasValue("Suspicious device activity <script>");analyst.locator("input[type=file]").setInputFiles(new FilePayload("security-proof.txt","text/plain","Captured endpoint evidence".getBytes()));analyst.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Upload").setExact(true)).press("Enter");analyst.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Investigate and respond")).press("Enter");analyst.getByLabel("Investigation classification",new Page.GetByLabelOptions().setExact(true)).selectOption("confirmed");analyst.getByLabel("Investigation findings").fill("Observed unauthorized activity; preserve evidence <script>");analyst.getByLabel("Security browser affected device",new Page.GetByLabelOptions().setExact(true)).check();analyst.getByLabel("security-proof.txt",new Page.GetByLabelOptions().setExact(true)).check();analyst.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save investigation").setExact(true)).press("Enter");assertThat(analyst.locator("main")).containsText("Investigation matches the current incident.");ReleaseBrowserAcceptance.accessible(analyst);analyst.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/security-investigation-light.png")).setFullPage(true));
   analyst.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Security incident workspace").setExact(true)).press("Enter");RiskAssessmentsBrowserAcceptance.change(analyst,"contain");analyst.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Investigate and respond")).press("Enter");analyst.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Coordinate response tasks")).press("Enter");analyst.getByLabel("Task summary",new Page.GetByLabelOptions().setExact(true)).fill("Contain the affected device");analyst.getByLabel("Task instructions",new Page.GetByLabelOptions().setExact(true)).fill("Isolate through the authorized endpoint console and verify");analyst.getByLabel("Responsible team",new Page.GetByLabelOptions().setExact(true)).selectOption(group);analyst.getByLabel("Completion requirement",new Page.GetByLabelOptions().setExact(true)).selectOption("true");analyst.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Create work task")).press("Enter");analyst.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Claim task").setExact(true)).press("Enter");analyst.getByLabel("Completion outcome").fill("Isolation and endpoint recovery verified in the authorized console");analyst.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Complete task").setExact(true)).press("Enter");analyst.navigate(h.base()+"/record/security_incident/"+id);RiskAssessmentsBrowserAcceptance.change(analyst,"review");analyst.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Investigate and respond")).press("Enter");analyst.getByLabel("Closure code",new Page.GetByLabelOptions().setExact(true)).selectOption("resolved");analyst.getByLabel("Closure review notes").fill("Evidence, containment and restored service independently checked");analyst.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save closure review")).press("Enter");analyst.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Request or review closure")).press("Enter");analyst.getByLabel("Reviewer username").fill("SecBrowserPeer");analyst.locator("select[name=target_state]").selectOption("closed");analyst.getByLabel("Reason for review").fill("Review the current investigation and response outcomes");analyst.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Request review").setExact(true)).press("Enter");
   var peer=pc.newPage();h.login(peer,"SecBrowserPeer");peer.navigate(h.base()+"/record/security_incident/"+id+"/response");assertThat(peer.locator("main")).containsText("Evidence, containment and restored service independently checked");peer.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Request or review closure")).press("Enter");peer.getByLabel("Decision",new Page.GetByLabelOptions().setExact(true)).selectOption("approved");peer.getByLabel("Review comment").fill("Incident evidence and response outcomes reviewed");peer.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Record decision")).press("Enter");analyst.navigate(h.base()+"/record/security_incident/"+id);RiskAssessmentsBrowserAcceptance.change(analyst,"closed");analyst.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Investigate and respond")).press("Enter");assertThat(analyst.locator("main")).containsText("Response phase: closed");analyst.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).press("Enter");analyst.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(analyst);assertEquals(false,analyst.evaluate("document.documentElement.scrollWidth>window.innerWidth"));assertThat(analyst.locator("main script")).hasCount(0);analyst.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/security-closed-dark.png")).setFullPage(true));
  }
 }
}
